import{_ as p,a0 as t,w as d,s as o,ao as r,I as l,x as a,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"把 Linux 上的文件列表和排序玩出花来 | LCTT x X-CMD","titleTemplate":false,"description":"把 Linux 上的文件列表和排序玩出花来 | LCTT (202008) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"把 Linux 上的文件列表和排序玩出花来 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"把 Linux 上的文件列表和排序玩出花来 | LCTT (202008) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202008/20200825 11 ways to list and sort files on Linux","title":"把 Linux 上的文件列表和排序玩出花来","tag":"202008","desc":""},"relativePath":"202008/20200825 11 ways to list and sort files on Linux.md","filePath":"[post].md"}'),c={name:"202008/20200825 11 ways to list and sort files on Linux.md"};function h(g,s,b,k,u,z){const n=t("Link");return d(),o("div",null,[s[15]||(s[15]=r(`<h1 id="把-linux-上的文件列表和排序玩出花来" tabindex="-1">把 Linux 上的文件列表和排序玩出花来 <a class="header-anchor" href="#把-linux-上的文件列表和排序玩出花来" aria-label="Permalink to “把 Linux 上的文件列表和排序玩出花来”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202008/28/213742y8cxnbnjpopzd5j0.jpg" alt=""></p><blockquote><p>Linux 命令可以提供文件的详细信息，也可以自定义显示的文件列表，甚至可以深入到文件系统的目录中，只要你愿意看。</p></blockquote><p>在 Linux 系统上，有许多方法可以列出文件并显示它们的信息。这篇文章回顾了一些提供文件细节的命令，并提供了自定义文件列表的选项，以满足你的需求。</p><p>大多数命令都会列出单个目录中的文件，而其他命令则可以深入到文件系统的目录中，只要你愿意看。</p><p>当然，最主要的文件列表命令是 <code>ls</code>。然而，这个命令有大量的选项，可以只查找和列出你想看的文件。另外，还有 <code>find</code> 可以帮助你进行非常具体的文件搜索。</p><h3 id="按名称列出文件" tabindex="-1">按名称列出文件 <a class="header-anchor" href="#按名称列出文件" aria-label="Permalink to “按名称列出文件”">​</a></h3><p>最简单的方法是使用 <code>ls</code> 命令按名称列出文件。毕竟，按名称（字母数字顺序）列出文件是默认的。你可以选择 <code>ls</code>（无细节）或 <code>ls -l</code>（大量细节）来决定你看到什么。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls | head -6</span></span>
<span class="line"><span>8pgs.pdf</span></span>
<span class="line"><span>Aesthetics_Thank_You.pdf</span></span>
<span class="line"><span>alien.pdf</span></span>
<span class="line"><span>Annual_Meeting_Agenda-20190602.pdf</span></span>
<span class="line"><span>bigfile.bz2</span></span>
<span class="line"><span>bin</span></span>
<span class="line"><span>$ ls -l | head -6</span></span>
<span class="line"><span>-rw-rw-r--  1 shs     shs      10886 Mar 22  2019 8pgs.pdf</span></span>
<span class="line"><span>-rw-rw-r--  1 shs     shs     284003 May 11  2019 Aesthetics_Thank_You.pdf</span></span>
<span class="line"><span>-rw-rw-r--  1 shs     shs      38282 Jan 24  2019 alien.pdf</span></span>
<span class="line"><span>-rw-rw-r--  1 shs     shs      97358 May 19  2019 Annual_Meeting_20190602.pdf</span></span>
<span class="line"><span>-rw-rw-r--  1 shs     shs   18115234 Apr 16 17:36 bigfile.bz2</span></span>
<span class="line"><span>drwxrwxr-x  4 shs     shs    8052736 Jul 10 13:17 bin</span></span></code></pre></div><p>如果你想一次查看一屏的列表，可以将 <code>ls</code> 的输出用管道送到 <code>more</code> 命令中。</p><h3 id="按相反的名字顺序排列文件" tabindex="-1">按相反的名字顺序排列文件 <a class="header-anchor" href="#按相反的名字顺序排列文件" aria-label="Permalink to “按相反的名字顺序排列文件”">​</a></h3><p>要按名称反转文件列表，请添加 <code>-r</code>（<ruby>反转<rt>Reverse</rt></ruby>）选项。这就像把正常的列表倒过来一样。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -r</span></span>
<span class="line"><span>$ ls -lr</span></span></code></pre></div><h3 id="按文件扩展名列出文件" tabindex="-1">按文件扩展名列出文件 <a class="header-anchor" href="#按文件扩展名列出文件" aria-label="Permalink to “按文件扩展名列出文件”">​</a></h3><p><code>ls</code> 命令不会按内容分析文件类型，它只会处理文件名。不过，有一个命令选项可以按扩展名列出文件。如果你添加了 <code>-X</code> （<ruby>扩展名<rt>eXtension</rt></ruby>）选项，<code>ls</code> 将在每个扩展名类别中按名称对文件进行排序。例如，它将首先列出没有扩展名的文件（按字母数字顺序），然后是扩展名为 <code>.1</code>、<code>.bz2</code>、<code>.c</code> 等的文件。</p><h3 id="只列出目录" tabindex="-1">只列出目录 <a class="header-anchor" href="#只列出目录" aria-label="Permalink to “只列出目录”">​</a></h3><p>默认情况下，<code>ls</code> 命令将同时显示文件和目录。如果你想只列出目录，你可以使用 <code>-d</code>（<ruby>目录<rt>Directory</rt></ruby>）选项。你会得到一个像这样的列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -d */</span></span>
<span class="line"><span>1/     backups/     modules/       projects/     templates/</span></span>
<span class="line"><span>2/     html/        patches/       public/       videos/</span></span>
<span class="line"><span>bin/   new/         private/       save/</span></span></code></pre></div><h3 id="按大小排列文件" tabindex="-1">按大小排列文件 <a class="header-anchor" href="#按大小排列文件" aria-label="Permalink to “按大小排列文件”">​</a></h3><p>如果你想按大小顺序列出文件，请添加 <code>-S</code>（<ruby>大小<rt>Size</rt></ruby>）选项。但请注意，这实际上不会显示文件的大小（以及其他文件的细节），除非你还添加 <code>-l</code>（<ruby>长列表<rt>Long listing</rt></ruby>）选项。当按大小列出文件时，一般来说，看到命令在按你的要求做事情是很有帮助的。注意，默认情况下是先显示最大的文件。添加 <code>-r</code> 选项可以反过来（即 <code>ls -lSr</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -lS</span></span>
<span class="line"><span>total 959492</span></span>
<span class="line"><span>-rw-rw-r--  1 shs   shs  357679381 Sep 19  2019 sav-linux-free-9.tgz</span></span>
<span class="line"><span>-rw-rw-r--  1 shs   shs  103270400 Apr 16 17:38 bigfile</span></span>
<span class="line"><span>-rw-rw-r--  1 shs   shs   79117862 Oct  5  2019 Nessus-8.7.1-ubuntu1110_amd64.deb</span></span></code></pre></div><h3 id="按属主列出文件" tabindex="-1">按属主列出文件 <a class="header-anchor" href="#按属主列出文件" aria-label="Permalink to “按属主列出文件”">​</a></h3><p>如果你想按属主列出文件（例如，在一个共享目录中），你可以把 <code>ls</code> 命令的输出传给 <code>sort</code>，并通过添加 <code>-k3</code> 来按第三个字段排序，从而挑出属主一栏。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l | sort -k3 | more</span></span>
<span class="line"><span>total 56</span></span>
<span class="line"><span>-rw-rw-r-- 1 dory  shs      0 Aug 23 12:27 tasklist</span></span>
<span class="line"><span>drwx------ 2 gdm   gdm   4096 Aug 21 17:12 tracker-extract-files.121</span></span>
<span class="line"><span>srwxr-xr-x 1 root  root     0 Aug 21 17:12 ntf_listenerc0c6b8b4567</span></span>
<span class="line"><span>drwxr-xr-x 2 root  root  4096 Aug 21 17:12 hsperfdata_root</span></span>
<span class="line"><span>              ^</span></span>
<span class="line"><span>              |</span></span></code></pre></div><p>事实上，你可以用这种方式对任何字段进行排序（例如，年份）。只是要注意，如果你要对一个数字字段进行排序，则要加上一个 <code>n</code>，如 <code>-k5n</code>，否则你将按字母数字顺序进行排序。这种排序技术对于文件内容的排序也很有用，而不仅仅是用于列出文件。</p><h3 id="按年份排列文件" tabindex="-1">按年份排列文件 <a class="header-anchor" href="#按年份排列文件" aria-label="Permalink to “按年份排列文件”">​</a></h3><p>使用 <code>-t</code>（<ruby>修改时间<rt>Time modified</rt></ruby>）选项按年份顺序列出文件 —— 它们的新旧程度。添加 <code>-r</code> 选项，让最近更新的文件在列表中最后显示。我使用这个别名来显示我最近更新的文件列表。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias recent=&#39;ls -ltr | tail -8&#39;</span></span></code></pre></div><p>请注意，文件的更改时间和修改时间是不同的。<code>-c</code>（<ruby>更改时间<rt>time Changed</rt></ruby>）和 <code>-t</code>（修改时间）选项的结果并不总是相同。如果你改变了一个文件的权限，而没有改变其他内容，<code>-c</code> 会把这个文件放在 <code>ls</code> 输出的顶部，而 <code>-t</code> 则不会。如果你想知道其中的区别，可以看看 <code>stat</code> 命令的输出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ stat ckacct</span></span>
<span class="line"><span>  File: ckacct</span></span>
<span class="line"><span>  Size: 200             Blocks: 8          IO Block: 4096   regular file</span></span>
<span class="line"><span>Device: 801h/2049d      Inode: 829041      Links: 1</span></span>
<span class="line"><span>Access: (0750/-rwxr-x---)  Uid: ( 1000/     shs)   Gid: ( 1000/     shs)</span></span>
<span class="line"><span>Access: 2020-08-20 16:10:11.063015008 -0400</span></span>
<span class="line"><span>Modify: 2020-08-17 07:26:34.579922297 -0400 &lt;== content changes</span></span>
<span class="line"><span>Change: 2020-08-24 09:36:51.699775940 -0400 &lt;== content or permissions changes</span></span>
<span class="line"><span> Birth: -</span></span></code></pre></div><h3 id="按组别列出文件" tabindex="-1">按组别列出文件 <a class="header-anchor" href="#按组别列出文件" aria-label="Permalink to “按组别列出文件”">​</a></h3><p>要按关联的组别对文件进行排序，你可以将一个长列表的输出传给 <code>sort</code> 命令，并告诉它在第 4 列进行排序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l | sort -k4</span></span></code></pre></div><h3 id="按访问日期列出文件" tabindex="-1">按访问日期列出文件 <a class="header-anchor" href="#按访问日期列出文件" aria-label="Permalink to “按访问日期列出文件”">​</a></h3><p>要按访问日期（最近访问的日期在前）列出文件，使用 <code>-ltu</code> 选项。<code>u</code> 强制“按访问日期”排列顺序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -ltu</span></span>
<span class="line"><span>total 959500</span></span>
<span class="line"><span>-rwxr-x---  1 shs     shs        200 Aug 24 09:42 ckacct  &lt;== most recently used</span></span>
<span class="line"><span>-rw-rw-r--  1 shs     shs       1335 Aug 23 17:45 lte</span></span></code></pre></div><h3 id="单行列出多个文件" tabindex="-1">单行列出多个文件 <a class="header-anchor" href="#单行列出多个文件" aria-label="Permalink to “单行列出多个文件”">​</a></h3><p>有时，精简的文件列表更适合手头的任务。<code>ls</code> 命令甚至有这方面的选项。为了在尽可能少的行上列出文件，你可以使用 <code>--format=comma</code> 来用逗号分隔文件名，就像这个命令一样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls --format=comma</span></span>
<span class="line"><span>1, 10, 11, 12, 124, 13, 14, 15, 16pgs-landscape.pdf, 16pgs.pdf, 17, 18, 19,</span></span>
<span class="line"><span>192.168.0.4, 2, 20, 2018-12-23_OoS_2.pdf, 2018-12-23_OoS.pdf, 20190512_OoS.pdf,</span></span>
<span class="line"><span>&#39;2019_HOHO_application working.pdf&#39; …</span></span></code></pre></div><p>喜欢用空格？使用 <code>--format=across</code> 代替。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls --format=across z*</span></span>
<span class="line"><span>z              zip            zipfiles      zipfiles1.bat   zipfiles2.bat</span></span>
<span class="line"><span>zipfiles3.bat  zipfiles4.bat  zipfiles.bat  zoom_amd64.deb  zoomap.pdf</span></span>
<span class="line"><span>zoom-mtg</span></span></code></pre></div><h3 id="增加搜索的深度" tabindex="-1">增加搜索的深度 <a class="header-anchor" href="#增加搜索的深度" aria-label="Permalink to “增加搜索的深度”">​</a></h3><p>虽然 <code>ls</code> 一般只列出单个目录中的文件，但你可以选择使用 <code>-R</code> 选项（<ruby>递归<rt>Recursively</rt></ruby>）地列出文件，深入到整个目录的深处。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -R zzzzz | grep -v &quot;^$&quot;</span></span>
<span class="line"><span>zzzzz:</span></span>
<span class="line"><span>zzzz</span></span>
<span class="line"><span>zzzzz/zzzz:</span></span>
<span class="line"><span>zzz</span></span>
<span class="line"><span>zzzzz/zzzz/zzz:</span></span>
<span class="line"><span>zz</span></span>
<span class="line"><span>zzzzz/zzzz/zzz/zz:</span></span>
<span class="line"><span>z</span></span>
<span class="line"><span>zzzzz/zzzz/zzz/zz/z:</span></span>
<span class="line"><span>sleeping</span></span></code></pre></div><p>另外，你也可以使用 <code>find</code> 命令，对深度进行限制或不限制。在这个命令中，我们指示 <code>find</code> 命令只在三个层次的目录中查找：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find zzzzz -maxdepth 3</span></span>
<span class="line"><span>zzzzz</span></span>
<span class="line"><span>zzzzz/zzzz</span></span>
<span class="line"><span>zzzzz/zzzz/zzz</span></span>
<span class="line"><span>zzzzz/zzzz/zzz/zz</span></span></code></pre></div><h3 id="选择-ls-还是-find" tabindex="-1">选择 ls 还是 find <a class="header-anchor" href="#选择-ls-还是-find" aria-label="Permalink to “选择 ls 还是 find”">​</a></h3><p>当你需要列出符合具体要求的文件时，<code>find</code> 命令可能是比 <code>ls</code> 更好的工具。</p><p>与 <code>ls</code> 不同的是，<code>find</code> 命令会尽可能地深入查找，除非你限制它。它还有许多其他选项和一个 <code>-exec</code> 子命令，允许在找到你要找的文件后采取一些特定的行动。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p><code>ls</code> 命令有很多用于列出文件的选项。了解一下它们。你可能会发现一些你会喜欢的选项。</p><hr>`,52)),l("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3572590/11-ways-to-list-and-sort-files-on-linux.html"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3572590/11-ways-to-list-and-sort-files-on-linux.html",-1)])]),_:1})]),l("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),l("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const y=p(c,[["render",h]]);export{x as __pageData,y as default};
